using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

// Register the chat client via MEAI abstraction
var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set AI:ApiKey in configuration or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseFunctionInvocation()
    .Use(new OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient()));

builder.Services.AddSingleton<NoteStore>();
builder.Services.AddSingleton<ResearchTools>();
builder.Services.AddHostedService<ResearchAgentService>();

var app = builder.Build();
await app.RunAsync();

// --- Note store (shared state for the note-taking tool) ---

public sealed class NoteStore
{
    private readonly List<string> _notes = [];

    public void Add(string note) => _notes.Add(note);

    public IReadOnlyList<string> GetAll() => _notes.AsReadOnly();
}

// --- Tools exposed to the agent ---

public sealed class ResearchTools(NoteStore noteStore)
{
    [Description("Search the web for information on a given query. Returns a list of relevant snippets.")]
    public static string WebSearch(
        [Description("The search query to look up on the web")] string query)
    {
        // Simulated web search results for demonstration purposes.
        // Replace with a real search API (Bing, Google, etc.) in production.
        return query.ToLowerInvariant() switch
        {
            var q when q.Contains("quantum computing") =>
                """
                [1] Quantum computing uses qubits that can exist in superposition, enabling parallel computation.
                [2] Google's Willow chip (2024) demonstrated quantum error correction below threshold.
                [3] IBM targets 100,000-qubit systems by 2033 for practical quantum advantage.
                [4] Key applications include cryptography, drug discovery, and optimization problems.
                """,
            var q when q.Contains("application") || q.Contains("use case") =>
                """
                [1] Pharmaceutical companies use quantum simulations to model molecular interactions.
                [2] Financial institutions explore quantum algorithms for portfolio optimization.
                [3] Logistics companies apply quantum annealing to route optimization.
                [4] Quantum machine learning may accelerate training of large AI models.
                """,
            _ =>
                $"""
                [1] Search results for "{query}": Multiple sources discuss recent advances in this area.
                [2] Experts suggest this field is rapidly evolving with new breakthroughs expected soon.
                [3] Industry adoption is growing, with several major companies investing heavily.
                """
        };
    }

    [Description("Save a research note for later summarization. Use this to record key findings.")]
    public string TakeNote(
        [Description("The note content to save")] string note)
    {
        noteStore.Add(note);
        return $"Note saved. Total notes: {noteStore.GetAll().Count}";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        var notes = noteStore.GetAll();
        return notes.Count == 0
            ? "No notes saved yet."
            : string.Join("\n", notes.Select((n, i) => $"[{i + 1}] {n}"));
    }
}

// --- Hosted service that runs the agent ---

public sealed class ResearchAgentService(
    IChatClient chatClient,
    ResearchTools tools,
    IHostApplicationLifetime lifetime) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        Console.WriteLine("=== Research Agent ===");
        Console.WriteLine("Enter a topic to research (or 'quit' to exit):\n");

        var topic = Console.ReadLine()?.Trim();
        if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        {
            lifetime.StopApplication();
            return;
        }

        Console.WriteLine($"\nResearching: {topic}\n");

        var chatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
            Tools = [
                AIFunctionFactory.Create(ResearchTools.WebSearch),
                AIFunctionFactory.Create(tools.TakeNote),
                AIFunctionFactory.Create(tools.GetNotes),
            ],
        };

        var systemPrompt = """
            You are a research agent. Your goal is to thoroughly research the given topic using the available tools.

            Follow this workflow:
            1. Search the web for information about the topic (use multiple searches with different queries).
            2. Take notes on key findings as you go.
            3. After gathering enough information, retrieve your notes and provide a comprehensive summary.

            Always take notes before summarizing. Be thorough but concise in your final summary.
            """;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, systemPrompt),
            new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
        };

        // Agent loop with iteration limit
        const int maxIterations = 15;
        var iteration = 0;

        while (iteration < maxIterations)
        {
            iteration++;
            var response = await chatClient.GetResponseAsync(messages, chatOptions, stoppingToken);

            // Add assistant response to history
            foreach (var msg in response.Messages)
            {
                messages.Add(msg);
            }

            // Check if the agent is done (no more tool calls pending)
            var lastMessage = response.Messages[^1];
            if (lastMessage.Role == ChatRole.Assistant &&
                lastMessage.Contents.All(c => c is not FunctionCallContent))
            {
                Console.WriteLine("--- Research Summary ---\n");
                Console.WriteLine(lastMessage.Text);
                break;
            }
        }

        if (iteration >= maxIterations)
        {
            Console.WriteLine("\n[Agent reached iteration limit]");
        }

        Console.WriteLine($"\n[Completed in {iteration} iteration(s)]");
        lifetime.StopApplication();
    }
}

